<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$auth->requireLogin();
function e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function uuidv4(): string { $d=random_bytes(16); $d[6]=chr((ord($d[6])&15)|64); $d[8]=chr((ord($d[8])&63)|128); return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4)); }
$role=(string)$auth->role(); $userId=(int)$auth->id(); $officeId=(int)($auth->officeId() ?? 0);
$propertyId=(int)($_GET['id'] ?? $_POST['property_id'] ?? 0); if($propertyId<1){http_response_code(400);exit('Invalid property.');}
$agentContextId=null;
if($role==='agent'){
 $s=$db->prepare('SELECT id,office_id FROM agents WHERE user_id=:u AND deleted_at IS NULL AND is_active=1 LIMIT 1'); $s->execute(['u'=>$userId]); $a=$s->fetch();
 if(!$a){http_response_code(403);exit('No active agent profile.');} $agentContextId=(int)$a['id']; $officeId=(int)$a['office_id'];
}
function loadProperty(PDO $db,int $id): ?array {
 $s=$db->prepare('SELECT p.*,o.name office_name,CONCAT(a.first_name," ",a.last_name) agent_name,pt.code property_type_code,pt.name_key property_type_name_key FROM properties p INNER JOIN offices o ON o.id=p.office_id LEFT JOIN agents a ON a.id=p.agent_id LEFT JOIN property_types pt ON pt.id=p.property_type_id WHERE p.id=:id AND p.deleted_at IS NULL LIMIT 1');
 $s->execute(['id'=>$id]); return $s->fetch() ?: null;
}
$p=loadProperty($db,$propertyId); if(!$p){http_response_code(404);exit('Property not found.');}
if($role==='office_admin' && (int)$p['office_id']!==$officeId || $role==='agent' && ((int)$p['office_id']!==$officeId || (int)$p['agent_id']!==$agentContextId)){http_response_code(403);exit('Access denied.');}
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_property'])){
 try{
  \App\Csrf::verify($_POST['_csrf']??'');
  $allowed=['reference','status','transaction_type','title','description','price','living_area_m2','land_area_m2','bedrooms','bathrooms','year_built','address_line_1','address_line_2','postcode','city','region'];
  $v=[]; foreach($allowed as $k){$v[$k]=trim((string)($_POST[$k]??'')); $v[$k]=($v[$k]==='')?null:$v[$k];}
  if($v['reference']===null) throw new RuntimeException(__t('properties.error.reference','Reference is required.'));
  if(!in_array($v['status'],['draft','active','sold','rented','withdrawn'],true)) throw new RuntimeException(__t('properties.error.status','Invalid status.'));
  if(!in_array($v['transaction_type'],['sale','rent'],true)) throw new RuntimeException(__t('properties.error.transaction','Invalid transaction type.'));
  $hasPool=isset($_POST['has_pool'])?1:0; $featured=isset($_POST['is_featured'])?1:0; $published=isset($_POST['is_published'])?1:0;
  if($role==='agent') $published=0;
  $s=$db->prepare('UPDATE properties SET reference=:reference,status=:status,transaction_type=:transaction_type,title=:title,description=:description,price=:price,living_area_m2=:living_area_m2,land_area_m2=:land_area_m2,bedrooms=:bedrooms,bathrooms=:bathrooms,year_built=:year_built,has_pool=:has_pool,address_line_1=:address_line_1,address_line_2=:address_line_2,postcode=:postcode,city=:city,region=:region,is_featured=:is_featured,is_published=:is_published,published_at=CASE WHEN :published=1 AND published_at IS NULL THEN NOW() WHEN :published=0 THEN NULL ELSE published_at END WHERE id=:id AND deleted_at IS NULL');
  $v['has_pool']=$hasPool;$v['is_featured']=$featured;$v['is_published']=$published;$v['id']=$propertyId;$v['published']=$published;$s->execute($v);$message=__t('properties.saved','Property saved successfully.');$p=loadProperty($db,$propertyId);
 }catch(Throwable $x){$error=$x->getMessage();}
}
$mediaStmt=$db->prepare('SELECT id,public_id,original_filename,file_path,thumbnail_path,medium_path,large_path,alt_text,sort_order,is_primary,mime_type,file_size,width,height FROM property_media WHERE property_id=:p AND deleted_at IS NULL ORDER BY sort_order,id');$mediaStmt->execute(['p'=>$propertyId]);$media=$mediaStmt->fetchAll();
$csrf=\App\Csrf::token();
